    "title": "Rewriting Copyright Law for Generative AI Would Hurt Everyone",
    "url": "https://www.eff.org/deeplinks/2026/10/rewriting-copyright-law-generative-ai-would-hurt-everyone",
    "source": "EFF AI",
    "published": "2026-10-30T23:42:45.000Z",
    "image": "https://www.eff.org/files/banner_library/ai-scraping-v4b.jpg",
    "coverageSources": 1,
    "ranking": {
      "coverage": 0,
      "titleImpact": 0.252,
      "sourceAuthority": 0.5,
      "freshness": 0.8444,
      "feedPosition": 1,
      "novelty": 0.7517
    },
    "rankingReasons": [
      "real-world consequences",
      "specific details",
      "recognizable entities",
      "unusual language in the current story batch"
    ],
    "score": 0.4272,
    "doomIndexCoverageSources": 1,
